package model; import java.io.Serializable; import model.annotation.*; public class Customer implements Serializable, Cloneable { private static final long serialVersionUID=1L; @Id private final String customerId; @MaxLength(50) private String name; private String email,mobile; public Customer(String id,String n,String e,String m){customerId=id;name=n;email=e;mobile=m;} public String getCustomerId(){return customerId;} public String getName(){return name;} public String getEmail(){return email;} public String getMobile(){return mobile;} public Customer clone(){try{return (Customer)super.clone();}catch(CloneNotSupportedException e){throw new AssertionError(e);}} }
